written = skipped = 0
with open('data/wave_out_2026-07-24/bulk_011.rows.jsonl','w') as f:
    for r in rows:
        full = dict(r); full.update(STAMP)
        f.write(json.dumps(full) + '\n')
        mrow = {'_id': r['doc_id'], 'claim': r['claim'], 'operation': r['operation'],
                'trigger': r['trigger'], 'shelf_life': r['shelf_life']}
        mrow.update(STAMP)
        existing = col.find_one({'_id': r['doc_id']}, {'reviewed_by': 1})
        if existing and existing.get('reviewed_by'):
            skipped += 1
            continue
        col.replace_one({'_id': r['doc_id']}, mrow, upsert=True)
        written += 1

open('data/wave_out_2026-07-24/bulk_011.verdicts.jsonl','w').close()
print(f'rows={len(rows)} mongo_written={written} mongo_skipped_reviewed={skipped} verdicts=0')
